export default [
  { "id": "ct_t_spine_trauma", "title": "CT Th-spine trauma", "group": "Trauma", "section": "Spine", "priority": 10,
    "text": "Badanie: TK kręgosłupa piersiowego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nKyfoza piersiowa zachowana.\nPrawidłowe ustawienie trzonów kręgów oraz stawów międzywyrostkowych, bez cech przemieszczenia.\nTrzony kręgów o zachowanej wysokości.\nNie stwierdza się złamań trzonów, łuków ani wyrostków kręgów piersiowych.\nKanał kręgowy o prawidłowej szerokości, bez fragmentów kostnych w jego świetle.\nStawy żebrowo-kręgowe prawidłowo ustawione.\nBez krwiaka przykręgosłupowego. Prawidłowy obraz otaczających tkanek miękkich.\n\nW uwidocznionym zakresie bez cech odmy opłucnowej i bez płynu w jamach opłucnowych.\nUwidocznione odcinki żeber bez cech złamania.\n\nWnioski:\n- Bez cech świeżego złamania lub zwichnięcia kręgosłupa piersiowego." },
  { "id": "ct_whole_spine_trauma", "title": "CT Whole spine trauma", "group": "Trauma", "section": "Spine", "priority": 11,
    "text": "Badanie: TK całego kręgosłupa bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nKręgosłup szyjny:\nPrawidłowy obraz połączenia czaszkowo-szyjnego.\nPrawidłowe ustawienie trzonów kręgów oraz stawów międzywyrostkowych, bez cech przemieszczenia.\nTrzony kręgów o zachowanej wysokości.\nNie stwierdza się złamań.\nTkanki miękkie przedkręgowe nieposzerzone.\n\nKręgosłup piersiowy:\nPrawidłowe ustawienie trzonów kręgów oraz stawów międzywyrostkowych, bez cech przemieszczenia.\nTrzony kręgów o zachowanej wysokości.\nNie stwierdza się złamań. Bez krwiaka przykręgosłupowego.\n\nKręgosłup lędźwiowy i kość krzyżowa:\nPrawidłowe ustawienie trzonów kręgów oraz stawów międzywyrostkowych, bez cech przemieszczenia.\nTrzony kręgów o zachowanej wysokości.\nNie stwierdza się złamań trzonów, łuków ani wyrostków poprzecznych.\nKość krzyżowa bez cech złamania. Stawy krzyżowo-biodrowe prawidłowo ustawione.\n\nKanał kręgowy na całej długości o prawidłowej szerokości, bez fragmentów kostnych w jego świetle.\nW uwidocznionym zakresie bez cech odmy opłucnowej. Uwidocznione odcinki żeber bez cech złamania.\n\nWnioski:\n- Bez cech świeżego złamania lub zwichnięcia kręgosłupa szyjnego, piersiowego i lędźwiowego." },
  { "id": "ct_sacrum_coccyx_trauma", "title": "CT Sacrum/coccyx trauma", "group": "Trauma", "section": "Spine", "priority": 12,
    "text": "Badanie: TK kości krzyżowej i guzicznej bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nKość krzyżowa bez cech złamania, z zachowaną ciągłością warstwy korowej, w tym w obrębie otworów krzyżowych.\nKość guziczna bez cech złamania. Ustawienie kości guzicznej w granicach zmienności osobniczej.\nStawy krzyżowo-biodrowe symetryczne, prawidłowo ustawione, szpary stawowe nieposzerzone.\nKanał krzyżowy o prawidłowej szerokości.\nBez krwiaka przedkrzyżowego. Prawidłowy obraz otaczających tkanek miękkich.\n\nUwidocznione fragmenty kości biodrowych oraz kręgu L5 bez cech złamania.\n\nWnioski:\n- Bez cech świeżego złamania kości krzyżowej i guzicznej." },
  { "id": "ct_l_spine_nontrauma", "title": "CT L-spine non-trauma", "group": "Non-trauma", "section": "Spine", "priority": 10,
    "text": "Badanie: TK kręgosłupa lędźwiowego bez kontrastu\n\nOpis:\nLordoza lędźwiowa zachowana. Ustawienie trzonów kręgów prawidłowe, bez cech kręgozmyku.\nTrzony kręgów o zachowanej wysokości, bez zmian ogniskowych w oknie kostnym.\nKrążki międzykręgowe bez cech przepuklin w zakresie oceny TK.\nKanał kręgowy o prawidłowej szerokości. Otwory międzykręgowe drożne.\nStawy międzywyrostkowe bez istotnych zmian zwyrodnieniowych.\nTkanki miękkie przykręgosłupowe bez zmian.\n\nW uwidocznionym zakresie przestrzeni zaotrzewnowej bez istotnych odchyleń.\nUwidocznione fragmenty stawów krzyżowo-biodrowych bez istotnych zmian.\n\nWnioski:\n- Obraz TK kręgosłupa lędźwiowego bez istotnych odchyleń od normy." },
  { "id": "mr_c_spine_normal", "title": "MR C-spine normal", "group": "Non-trauma", "section": "Spine", "priority": 11,
    "text": "Badanie: MR kręgosłupa szyjnego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych i STIR, w płaszczyznach strzałkowej i poprzecznej.\n\nPołączenie czaszkowo-szyjne prawidłowe. Migdałki móżdżku położone prawidłowo.\nLordoza szyjna zachowana. Ustawienie trzonów kręgowych prawidłowe.\nTrzony kręgowe prawidłowej wysokości, o prawidłowym sygnale szpiku kostnego.\nKrążki międzykręgowe prawidłowej wysokości, bez cech przepuklin.\nKanał kręgowy o prawidłowej szerokości. Otwory międzykręgowe drożne.\nRdzeń kręgowy szyjny prawidłowej grubości, o prawidłowym sygnale, bez cech ucisku.\nStawy międzywyrostkowe i unkowertebralne bez istotnych zmian zwyrodnieniowych.\nTkanki miękkie przykręgosłupowe bez zmian.\n\nWnioski:\n- Obraz MR kręgosłupa szyjnego bez istotnych odchyleń od normy." },
  { "id": "mr_t_spine_normal", "title": "MR Th-spine normal", "group": "Non-trauma", "section": "Spine", "priority": 12,
    "text": "Badanie: MR kręgosłupa piersiowego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych i STIR, w płaszczyznach strzałkowej i poprzecznej.\n\nKyfoza piersiowa zachowana. Ustawienie trzonów kręgowych prawidłowe.\nTrzony kręgowe prawidłowej wysokości, o prawidłowym sygnale szpiku kostnego.\nKrążki międzykręgowe prawidłowej wysokości, bez cech przepuklin.\nKanał kręgowy o prawidłowej szerokości. Otwory międzykręgowe drożne.\nRdzeń kręgowy piersiowy prawidłowej grubości, o prawidłowym sygnale, bez cech ucisku.\nW uwidocznionym zakresie stożek rdzeniowy prawidłowo położony.\nTkanki miękkie przykręgosłupowe bez zmian.\n\nWnioski:\n- Obraz MR kręgosłupa piersiowego bez istotnych odchyleń od normy." },
  { "id": "mr_whole_spine_cord_compression", "title": "MR Whole spine (ucisk rdzenia) normal", "group": "Non-trauma", "section": "Spine", "priority": 13,
    "text": "Badanie: MR całego kręgosłupa bez kontrastu – w kierunku ucisku rdzenia kręgowego\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym, w sekwencjach T1-, T2-zależnych i STIR w płaszczyźnie strzałkowej całego kręgosłupa oraz T2-zależnych w płaszczyźnie poprzecznej na wybranych poziomach.\n\nUstawienie trzonów kręgowych prawidłowe.\nTrzony kręgów szyjnych, piersiowych i lędźwiowych o zachowanej wysokości i prawidłowym sygnale szpiku kostnego.\nNie uwidoczniono zmian ogniskowych w trzonach ani w elementach tylnych kręgów.\nKanał kręgowy na całej długości o prawidłowej szerokości.\nNie uwidoczniono mas ani zbiorników płynowych w przestrzeni nadoponowej.\nRdzeń kręgowy prawidłowej grubości, o prawidłowym sygnale, bez cech ucisku.\nStożek rdzeniowy prawidłowo położony. Korzenie ogona końskiego swobodnie ułożone.\nTkanki miękkie przykręgosłupowe bez zmian.\n\nWnioski:\n- Bez cech ucisku rdzenia kręgowego ani ogona końskiego.\n- Nie uwidoczniono zmian ogniskowych w obrębie kręgosłupa." },
  { "id": "mr_spine_spondylodiscitis", "title": "MR Spine contrast (spondylodiscitis)", "group": "Non-trauma", "section": "Spine", "priority": 14,
    "text": "Badanie: MR kręgosłupa lędźwiowego bez i po dożylnym podaniu środka kontrastowego\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych i STIR oraz T1-zależnych z saturacją tłuszczu po dożylnym podaniu środka kontrastowego, w płaszczyznach strzałkowej i poprzecznej.\n\nUstawienie trzonów kręgowych prawidłowe.\nTrzony kręgowe prawidłowej wysokości, o prawidłowym sygnale szpiku kostnego, bez cech obrzęku szpiku.\nPłytki graniczne trzonów o gładkich zarysach, bez cech destrukcji.\nKrążki międzykręgowe prawidłowej wysokości, bez podwyższenia sygnału w obrazach T2-zależnych i bez patologicznego wzmocnienia kontrastowego.\nNie uwidoczniono ropnia nadoponowego ani zbiorników płynowych przykręgosłupowych.\nMięśnie lędźwiowe i przykręgosłupowe o prawidłowym sygnale, bez patologicznego wzmocnienia kontrastowego.\nKanał kręgowy o prawidłowej szerokości. Stożek rdzeniowy prawidłowo położony, o prawidłowym sygnale.\n\nWnioski:\n- Bez cech zapalenia krążka międzykręgowego i trzonów kręgów.\n- Bez cech ropnia nadoponowego i przykręgosłupowego." },
  { "id": "mr_c_spine_trauma", "title": "MR C-spine trauma", "group": "Trauma", "section": "Spine", "priority": 13,
    "text": "Badanie: MR kręgosłupa szyjnego bez kontrastu – po urazie\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych i STIR, w płaszczyznach strzałkowej i poprzecznej.\n\nPrawidłowy obraz połączenia czaszkowo-szyjnego.\nPrawidłowe ustawienie trzonów kręgów oraz stawów międzywyrostkowych.\nBez obrzęku szpiku kostnego w trzonach i elementach tylnych kręgów.\nWięzadła podłużne przednie i tylne ciągłe. Więzadła żółte, międzykolcowe i nadkolcowe bez cech uszkodzenia.\nKrążki międzykręgowe bez cech pourazowego uszkodzenia, bez przepuklin.\nKanał kręgowy o prawidłowej szerokości. Bez krwiaka nadoponowego.\nRdzeń kręgowy prawidłowej grubości, o prawidłowym sygnale, bez cech stłuczenia, obrzęku ani krwawienia.\nW tętnicach kręgowych zachowany prawidłowy obraz przepływu (flow void).\nTkanki miękkie przedkręgowe bez obrzęku i bez krwiaka.\n\nWnioski:\n- Bez cech pourazowego uszkodzenia kręgosłupa szyjnego, aparatu więzadłowego i rdzenia kręgowego." },
  { "id": "xr_c_spine_trauma", "title": "RTG C-spine", "group": "Trauma", "section": "Spine", "priority": 14,
    "text": "Badanie: RTG kręgosłupa szyjnego w projekcjach AP, bocznej i celowanej na ząb kręgu obrotowego\n\nOpis:\nKręgosłup szyjny uwidoczniony do poziomu C7/Th1.\nLordoza szyjna zachowana.\nPrawidłowe ustawienie kręgów – zachowana ciągłość linii przedniej i tylnej trzonów oraz linii rdzeniowo-blaszkowej.\nTrzony kręgów o zachowanej wysokości. Przestrzenie międzykręgowe zachowane.\nNie uwidoczniono linii złamań.\nZąb kręgu obrotowego bez cech złamania, symetrycznie położony między częściami bocznymi kręgu szczytowego.\nOdstęp szczytowo-zębowy prawidłowy.\nTkanki miękkie przedkręgowe nieposzerzone.\n\nWnioski:\n- Bez radiologicznych cech świeżego złamania lub zwichnięcia kręgosłupa szyjnego." },
  { "id": "xr_t_spine_trauma", "title": "RTG Th-spine", "group": "Trauma", "section": "Spine", "priority": 15,
    "text": "Badanie: RTG kręgosłupa piersiowego w projekcjach AP i bocznej\n\nOpis:\nKyfoza piersiowa zachowana. Ustawienie trzonów kręgów prawidłowe.\nTrzony kręgów o zachowanej wysokości. Przestrzenie międzykręgowe zachowane.\nNie uwidoczniono linii złamań.\nNasady łuków kręgowych widoczne obustronnie, odległości między nimi prawidłowe.\nLinie przykręgosłupowe nieposzerzone.\n\nWnioski:\n- Bez radiologicznych cech świeżego złamania kręgosłupa piersiowego." },
  { "id": "xr_l_spine_trauma", "title": "RTG L-spine", "group": "Trauma", "section": "Spine", "priority": 16,
    "text": "Badanie: RTG kręgosłupa lędźwiowego w projekcjach AP i bocznej\n\nOpis:\nLordoza lędźwiowa zachowana. Ustawienie trzonów kręgów prawidłowe, bez cech kręgozmyku.\nTrzony kręgów o zachowanej wysokości. Przestrzenie międzykręgowe zachowane.\nNie uwidoczniono linii złamań trzonów ani wyrostków poprzecznych.\nNasady łuków kręgowych widoczne obustronnie, odległości między nimi prawidłowe.\nUwidocznione fragmenty stawów krzyżowo-biodrowych bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżego złamania kręgosłupa lędźwiowego." },
  { "id": "ct_shoulder_trauma", "title": "CT Shoulder trauma", "group": "Trauma", "section": "Upper limb", "priority": 10,
    "text": "Badanie: TK stawu barkowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nGłowa kości ramiennej prawidłowo położona względem panewki stawowej łopatki, bez cech zwichnięcia.\nNie uwidoczniono złamania nasady bliższej kości ramiennej, w tym guzka większego i mniejszego.\nPanewka stawowa łopatki bez cech złamania, z zachowanym zarysem brzegu przednio-dolnego.\nBez cech wgłobienia na tylno-bocznym zarysie głowy kości ramiennej (Hill-Sachs).\nTrzon łopatki, wyrostek kruczy i wyrostek barkowy bez cech złamania.\nStaw barkowo-obojczykowy prawidłowo ustawiony. Uwidoczniony fragment obojczyka bez cech złamania.\nBez wysięku w stawie. Tkanki miękkie bez krwiaka.\n\nW uwidocznionym zakresie bez cech odmy opłucnowej. Uwidocznione żebra bez cech złamania.\n\nWnioski:\n- Bez cech zmian pourazowych w obrębie stawu barkowego i obręczy barkowej." },
  { "id": "ct_elbow_trauma", "title": "CT Elbow trauma", "group": "Trauma", "section": "Upper limb", "priority": 11,
    "text": "Badanie: TK stawu łokciowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPrawidłowe ustawienie w stawach ramienno-łokciowym, ramienno-promieniowym i promieniowo-łokciowym bliższym.\nNie uwidoczniono złamań nasady dalszej kości ramiennej, w tym kłykci i nadkłykci.\nGłowa i szyjka kości promieniowej bez cech złamania.\nWyrostek łokciowy i wyrostek dziobiasty kości łokciowej bez cech złamania.\nBez wolnych fragmentów kostnych w jamie stawu.\nBez wysięku w stawie. Tkanki miękkie bez istotnych zmian pourazowych.\n\nWnioski:\n- Bez cech zmian pourazowych w obrębie stawu łokciowego." },
  { "id": "ct_wrist_trauma", "title": "CT Wrist / scaphoid trauma", "group": "Trauma", "section": "Upper limb", "priority": 12,
    "text": "Badanie: TK nadgarstka prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nNasady dalsze kości promieniowej i łokciowej bez cech złamania. Powierzchnia stawowa kości promieniowej gładka.\nKość łódeczkowata bez cech złamania, z zachowaną ciągłością warstwy korowej.\nPozostałe kości nadgarstka bez cech złamania.\nPrawidłowe ustawienie kości nadgarstka, szpara łódeczkowato-księżycowata nieposzerzona.\nStaw promieniowo-łokciowy dalszy prawidłowo ustawiony.\nPodstawy kości śródręcza bez cech złamania, stawy nadgarstkowo-śródręczne prawidłowo ustawione.\nTkanki miękkie bez istotnych zmian pourazowych.\n\nWnioski:\n- Bez cech złamania kości nadgarstka, w tym kości łódeczkowatej.\n- Bez cech złamania nasad dalszych kości przedramienia." },
  { "id": "mr_shoulder_normal", "title": "MR Shoulder normal", "group": "Non-trauma", "section": "Upper limb", "priority": 10,
    "text": "Badanie: MR stawu barkowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach PD-zależnych z saturacją tłuszczu, T1- i T2-zależnych, w płaszczyznach skośnej czołowej, skośnej strzałkowej i poprzecznej.\n\nŚcięgna mięśni nadgrzebieniowego, podgrzebieniowego, podłopatkowego i obłego mniejszego ciągłe, o prawidłowej grubości i sygnale, bez cech rozdarcia.\nBrzuśce mięśni stożka rotatorów bez cech zaniku i stłuszczenia.\nŚcięgno głowy długiej mięśnia dwugłowego ramienia prawidłowo położone w bruździe międzyguzkowej, o prawidłowym sygnale.\nObrąbek stawowy bez widocznych cech uszkodzenia (ocena ograniczona w badaniu bez artrografii).\nChrząstka stawowa zachowana. Bez wysięku w stawie ramiennym.\nKaletka podbarkowo-podnaramienna bez płynu. Przestrzeń podbarkowa niezwężona.\nStaw barkowo-obojczykowy bez istotnych zmian zwyrodnieniowych.\nSzpik kostny o prawidłowym sygnale.\n\nWnioski:\n- Obraz MR stawu barkowego bez istotnych odchyleń od normy." },
  { "id": "mr_wrist_normal", "title": "MR Wrist normal", "group": "Non-trauma", "section": "Upper limb", "priority": 11,
    "text": "Badanie: MR nadgarstka prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach T1-zależnych, PD-zależnych z saturacją tłuszczu i STIR, w płaszczyznach czołowej, strzałkowej i poprzecznej.\n\nKości nadgarstka i nasady dalsze kości przedramienia o prawidłowym sygnale szpiku, bez obrzęku szpiku i bez linii złamań.\nKość łódeczkowata i kość księżycowata o prawidłowym sygnale, bez cech martwicy.\nPrawidłowe ustawienie kości nadgarstka.\nKompleks chrząstki trójkątnej (TFCC) bez cech uszkodzenia.\nWięzadła łódeczkowato-księżycowate i księżycowato-trójgraniaste ciągłe.\nŚcięgna zginaczy i prostowników o prawidłowym przebiegu i sygnale, bez płynu w pochewkach ścięgnistych.\nNerw pośrodkowy w kanale nadgarstka prawidłowej grubości i sygnału.\nBez wysięku w stawach. Bez zmian ogniskowych w tkankach miękkich.\n\nWnioski:\n- Obraz MR nadgarstka bez istotnych odchyleń od normy." },
  { "id": "xr_shoulder", "title": "RTG Shoulder", "group": "Trauma", "section": "Upper limb", "priority": 13,
    "text": "Badanie: RTG stawu barkowego prawego/lewego w projekcjach AP i osiowej\n\nOpis:\nPrawidłowe ustawienie głowy kości ramiennej względem panewki stawowej łopatki, bez cech zwichnięcia.\nNie uwidoczniono linii złamań w obrębie nasady bliższej kości ramiennej, łopatki i obojczyka.\nStaw barkowo-obojczykowy prawidłowo ustawiony.\nPrzestrzeń podbarkowa zachowana.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu barkowego." },
  { "id": "xr_clavicle", "title": "RTG Clavicle", "group": "Trauma", "section": "Upper limb", "priority": 14,
    "text": "Badanie: RTG obojczyka prawego/lewego\n\nOpis:\nObojczyk bez cech złamania, z zachowaną ciągłością warstwy korowej na całej długości.\nStaw barkowo-obojczykowy prawidłowo ustawiony, odstęp kruczo-obojczykowy prawidłowy.\nW uwidocznionym zakresie żebra bez cech złamania, bez cech odmy opłucnowej w szczycie płuca.\n\nWnioski:\n- Bez radiologicznych cech złamania obojczyka i zwichnięcia w stawie barkowo-obojczykowym." },
  { "id": "xr_humerus", "title": "RTG Humerus", "group": "Trauma", "section": "Upper limb", "priority": 15,
    "text": "Badanie: RTG kości ramiennej prawej/lewej w projekcjach AP i bocznej\n\nOpis:\nKość ramienna bez cech złamania na całej długości, z zachowaną ciągłością warstwy korowej.\nUwidocznione fragmenty stawów barkowego i łokciowego prawidłowo ustawione.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości ramiennej." },
  { "id": "xr_elbow", "title": "RTG Elbow", "group": "Trauma", "section": "Upper limb", "priority": 16,
    "text": "Badanie: RTG stawu łokciowego prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nPrawidłowe ustawienie w stawie łokciowym. Oś długa kości promieniowej przechodzi przez główkę kości ramiennej.\nNie uwidoczniono linii złamań w obrębie nasady dalszej kości ramiennej, głowy kości promieniowej i wyrostka łokciowego.\nSzpara stawowa zachowana.\nPrzednia poduszeczka tłuszczowa nieuniesiona, tylna niewidoczna – bez pośrednich cech wysięku w stawie.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu łokciowego." },
  { "id": "xr_forearm", "title": "RTG Forearm", "group": "Trauma", "section": "Upper limb", "priority": 17,
    "text": "Badanie: RTG przedramienia prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nKości promieniowa i łokciowa bez cech złamania na całej długości.\nUwidocznione stawy łokciowy i promieniowo-nadgarstkowy prawidłowo ustawione.\nBez cech zwichnięcia w stawach promieniowo-łokciowych bliższym i dalszym.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości przedramienia." },
  { "id": "xr_wrist", "title": "RTG Wrist", "group": "Trauma", "section": "Upper limb", "priority": 18,
    "text": "Badanie: RTG nadgarstka prawego/lewego w projekcjach PA i bocznej\n\nOpis:\nNasady dalsze kości promieniowej i łokciowej bez cech złamania.\nPrawidłowe nachylenie powierzchni stawowej kości promieniowej.\nKości nadgarstka bez widocznych linii złamań, prawidłowo ustawione, łuki nadgarstka zachowane.\nKość księżycowata prawidłowo ustawiona względem kości promieniowej i główkowatej.\nSzpary stawowe zachowane.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie nadgarstka." },
  { "id": "xr_scaphoid", "title": "RTG Scaphoid series", "group": "Trauma", "section": "Upper limb", "priority": 19,
    "text": "Badanie: RTG nadgarstka prawego/lewego – seria celowana na kość łódeczkowatą\n\nOpis:\nKość łódeczkowata bez widocznej linii złamania, z zachowaną ciągłością warstwy korowej.\nPasek tłuszczu przy kości łódeczkowatej zachowany.\nSzpara łódeczkowato-księżycowata nieposzerzona.\nPozostałe kości nadgarstka oraz nasada dalsza kości promieniowej bez cech złamania.\n\nWnioski:\n- Bez radiologicznych cech złamania kości łódeczkowatej.\n- Przy utrzymujących się objawach klinicznych do rozważenia MR lub kontrolne RTG po 10–14 dniach." },
  { "id": "xr_hand", "title": "RTG Hand", "group": "Trauma", "section": "Upper limb", "priority": 20,
    "text": "Badanie: RTG ręki prawej/lewej w projekcjach PA i skośnej\n\nOpis:\nKości śródręcza i paliczki bez cech złamania.\nPrawidłowe ustawienie w stawach nadgarstkowo-śródręcznych, śródręczno-paliczkowych i międzypaliczkowych.\nSzpary stawowe zachowane.\nBez cieniujących ciał obcych w tkankach miękkich.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie ręki." },
  { "id": "xr_finger", "title": "RTG Finger", "group": "Trauma", "section": "Upper limb", "priority": 21,
    "text": "Badanie: RTG palca … ręki prawej/lewej w projekcjach PA i bocznej\n\nOpis:\nPaliczki bez cech złamania.\nPrawidłowe ustawienie w stawach śródręczno-paliczkowym i międzypaliczkowych, bez cech zwichnięcia.\nSzpary stawowe zachowane.\nBez cieniujących ciał obcych w tkankach miękkich.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie palca." },
  { "id": "ct_knee_trauma", "title": "CT Knee / tibial plateau trauma", "group": "Trauma", "section": "Lower limb", "priority": 10,
    "text": "Badanie: TK stawu kolanowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPrawidłowe ustawienie w stawach udowo-piszczelowym i udowo-rzepkowym.\nKłykcie kości udowej bez cech złamania.\nKłykcie kości piszczelowej bez cech złamania, powierzchnie stawowe gładkie, bez zapadnięcia.\nWyniosłość międzykłykciowa bez cech oderwania.\nGłowa kości strzałkowej bez cech złamania.\nRzepka bez cech złamania, prawidłowo położona.\nBez wysięku w stawie, bez poziomu płyn–tłuszcz. Tkanki miękkie bez istotnych zmian pourazowych.\n\nWnioski:\n- Bez cech zmian pourazowych w obrębie stawu kolanowego." },
  { "id": "ct_ankle_trauma", "title": "CT Ankle / pilon trauma", "group": "Trauma", "section": "Lower limb", "priority": 11,
    "text": "Badanie: TK stawu skokowo-goleniowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nNasada dalsza kości piszczelowej bez cech złamania, z zachowaną powierzchnią stawową.\nKostki przyśrodkowa, boczna i tylna bez cech złamania.\nPrawidłowe ustawienie kości piszczelowej i strzałkowej w obrębie więzozrostu piszczelowo-strzałkowego dalszego.\nPrawidłowe ustawienie w stawie skokowo-goleniowym, szpara stawowa równomierna.\nKość skokowa bez cech złamania, kopuła kości skokowej o zachowanym zarysie.\nUwidocznione fragmenty kości piętowej i pozostałych kości stępu bez cech złamania.\nBez wysięku w stawie. Tkanki miękkie bez istotnych zmian pourazowych.\n\nWnioski:\n- Bez cech zmian pourazowych w obrębie stawu skokowo-goleniowego." },
  { "id": "ct_foot_trauma", "title": "CT Foot / calcaneus trauma", "group": "Trauma", "section": "Lower limb", "priority": 12,
    "text": "Badanie: TK stopy prawej/lewej bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nKość piętowa bez cech złamania, z zachowaną tylną powierzchnią stawową podskokową.\nKość skokowa bez cech złamania.\nPrawidłowe ustawienie w stawie skokowo-piętowym oraz w stawie poprzecznym stępu (Choparta).\nKości łódkowata, sześcienna i klinowate bez cech złamania.\nPrawidłowe ustawienie w stawach stępowo-śródstopnych (Lisfranca), bez poszerzenia przestrzeni między podstawami I i II kości śródstopia.\nKości śródstopia i uwidocznione paliczki bez cech złamania.\nTkanki miękkie bez istotnych zmian pourazowych.\n\nWnioski:\n- Bez cech zmian pourazowych w obrębie kości stopy." },
  { "id": "mr_knee_normal", "title": "MR Knee normal", "group": "Non-trauma", "section": "Lower limb", "priority": 10,
    "text": "Badanie: MR stawu kolanowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach PD-zależnych z saturacją tłuszczu w trzech płaszczyznach oraz T1-zależnych w płaszczyźnie czołowej.\n\nŁąkotki przyśrodkowa i boczna o prawidłowym kształcie i sygnale, bez cech rozdarcia.\nWięzadła krzyżowe przednie i tylne ciągłe, o prawidłowym przebiegu i sygnale.\nWięzadła poboczne piszczelowe i strzałkowe ciągłe.\nŚcięgno mięśnia czworogłowego uda i więzadło rzepki prawidłowe.\nChrząstka stawowa przedziałów przyśrodkowego, bocznego i udowo-rzepkowego zachowana.\nRzepka prawidłowo położona.\nSzpik kostny o prawidłowym sygnale, bez obrzęku szpiku i bez linii złamań.\nNiewielka, fizjologiczna ilość płynu w stawie. Bez torbieli podkolanowej.\nTkanki miękkie okołostawowe bez zmian.\n\nWnioski:\n- Obraz MR stawu kolanowego bez istotnych odchyleń od normy." },
  { "id": "mr_ankle_normal", "title": "MR Ankle normal", "group": "Non-trauma", "section": "Lower limb", "priority": 11,
    "text": "Badanie: MR stawu skokowo-goleniowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach PD-zależnych z saturacją tłuszczu, T1-zależnych i STIR, w płaszczyznach strzałkowej, czołowej i poprzecznej.\n\nŚcięgno Achillesa ciągłe, prawidłowej grubości i sygnału.\nŚcięgna mięśni strzałkowych, piszczelowego tylnego, zginaczy i prostowników ciągłe, o prawidłowym sygnale, bez płynu w pochewkach ścięgnistych ponad ilość fizjologiczną.\nWięzadła skokowo-strzałkowe przednie i tylne oraz piętowo-strzałkowe ciągłe.\nWięzadło trójgraniaste ciągłe.\nWięzozrost piszczelowo-strzałkowy dalszy bez cech uszkodzenia.\nKopuła kości skokowej o zachowanej chrząstce, bez zmian kostno-chrzęstnych.\nSzpik kostny o prawidłowym sygnale, bez obrzęku szpiku.\nZatoka stępu bez zmian. Rozcięgno podeszwowe prawidłowej grubości.\nBez wysięku w stawie.\n\nWnioski:\n- Obraz MR stawu skokowo-goleniowego bez istotnych odchyleń od normy." },
  { "id": "mr_soft_tissue_mass", "title": "MR Soft tissue mass (kończyna)", "group": "Non-trauma", "section": "Lower limb", "priority": 12,
    "text": "Badanie: MR tkanek miękkich okolicy … bez i po dożylnym podaniu środka kontrastowego\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych, STIR oraz T1-zależnych z saturacją tłuszczu po dożylnym podaniu środka kontrastowego, w trzech płaszczyznach.\n\nW ocenianej okolicy nie uwidoczniono zmiany ogniskowej w tkankach miękkich.\nTkanka podskórna bez zmian.\nMięśnie o prawidłowym sygnale i zarysach, bez obrzęku.\nPęczki naczyniowo-nerwowe o prawidłowym przebiegu.\nNie uwidoczniono patologicznego wzmocnienia kontrastowego.\nBez powiększonych węzłów chłonnych w zakresie badania.\n\nUwidocznione struktury kostne o prawidłowym sygnale szpiku.\n\nWnioski:\n- W ocenianej okolicy nie uwidoczniono zmiany ogniskowej w tkankach miękkich." },
  { "id": "xr_femur", "title": "RTG Femur", "group": "Trauma", "section": "Lower limb", "priority": 13,
    "text": "Badanie: RTG kości udowej prawej/lewej w projekcjach AP i bocznej\n\nOpis:\nKość udowa bez cech złamania na całej długości, z zachowaną ciągłością warstwy korowej.\nUwidocznione fragmenty stawów biodrowego i kolanowego prawidłowo ustawione.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości udowej." },
  { "id": "xr_knee", "title": "RTG Knee", "group": "Trauma", "section": "Lower limb", "priority": 14,
    "text": "Badanie: RTG stawu kolanowego prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nPrawidłowe ustawienie w stawie kolanowym.\nNie uwidoczniono linii złamań w obrębie nasady dalszej kości udowej, nasady bliższej kości piszczelowej, głowy kości strzałkowej i rzepki.\nSzpary stawowe przedziałów przyśrodkowego i bocznego zachowane.\nRzepka prawidłowo położona.\nW projekcji bocznej bez cech wysięku w zachyłku nadrzepkowym.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu kolanowego." },
  { "id": "xr_tibia_fibula", "title": "RTG Tibia/fibula", "group": "Trauma", "section": "Lower limb", "priority": 15,
    "text": "Badanie: RTG podudzia prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nKości piszczelowa i strzałkowa bez cech złamania na całej długości.\nUwidocznione fragmenty stawów kolanowego i skokowo-goleniowego prawidłowo ustawione.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości podudzia." },
  { "id": "xr_ankle", "title": "RTG Ankle", "group": "Trauma", "section": "Lower limb", "priority": 16,
    "text": "Badanie: RTG stawu skokowo-goleniowego prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nPrawidłowe ustawienie w stawie skokowo-goleniowym, szpara stawowa równomierna.\nKostki przyśrodkowa, boczna i tylna bez cech złamania.\nPrzestrzeń przyśrodkowa nieposzerzona.\nKość skokowa bez cech złamania.\nUwidocznione fragmenty kości piętowej i podstawy V kości śródstopia bez cech złamania.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu skokowo-goleniowego." },
  { "id": "xr_foot", "title": "RTG Foot", "group": "Trauma", "section": "Lower limb", "priority": 17,
    "text": "Badanie: RTG stopy prawej/lewej w projekcjach AP i skośnej\n\nOpis:\nKości stępu, śródstopia i paliczki bez cech złamania.\nPrawidłowe ustawienie w stawach stępowo-śródstopnych – przyśrodkowy zarys podstawy II kości śródstopia w jednej linii z przyśrodkowym zarysem kości klinowatej pośredniej.\nPodstawa V kości śródstopia bez cech złamania.\nSzpary stawowe zachowane.\nBez cieniujących ciał obcych w tkankach miękkich.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stopy." },
  { "id": "xr_calcaneus", "title": "RTG Calcaneus", "group": "Trauma", "section": "Lower limb", "priority": 18,
    "text": "Badanie: RTG kości piętowej prawej/lewej w projekcjach bocznej i osiowej\n\nOpis:\nKość piętowa bez cech złamania, z zachowaną ciągłością warstwy korowej.\nKąt Böhlera zachowany.\nUwidocznione stawy skokowo-piętowy i piętowo-sześcienny prawidłowo ustawione.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości piętowej." },
  { "id": "ct_pelvis_acetabulum_trauma", "title": "CT Pelvis / acetabulum trauma", "group": "Trauma", "section": "Pelvis / Hips", "priority": 10,
    "text": "Badanie: TK miednicy bez kontrastu – po urazie\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPierścień miednicy zachowany.\nKości biodrowe, łonowe i kulszowe bez cech złamania.\nPanewki stawów biodrowych bez cech złamania – kolumny przednia i tylna oraz ściany przednia i tylna zachowane.\nGłowy kości udowych prawidłowo osadzone w panewkach, bez cech złamania.\nSzyjki i okolice krętarzowe kości udowych bez cech złamania.\nSpojenie łonowe o prawidłowej szerokości.\nStawy krzyżowo-biodrowe symetryczne, nieposzerzone.\nKość krzyżowa i kość guziczna bez cech złamania.\n\nBez krwiaka w miednicy mniejszej i w tkankach miękkich. Pęcherz moczowy o prawidłowym zarysie.\nW uwidocznionym zakresie bez wolnego płynu i wolnego powietrza.\n\nWnioski:\n- Bez cech złamania miednicy i panewek stawów biodrowych.\n- Bez cech zwichnięcia stawów biodrowych." },
  { "id": "ct_hip_trauma", "title": "CT Hip trauma", "group": "Trauma", "section": "Pelvis / Hips", "priority": 11,
    "text": "Badanie: TK stawu biodrowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nGłowa kości udowej prawidłowo osadzona w panewce, bez cech złamania.\nSzyjka kości udowej bez cech złamania, z zachowaną ciągłością warstwy korowej i beleczkowania.\nKrętarz większy i mniejszy bez cech złamania.\nPanewka stawu biodrowego bez cech złamania.\nUwidocznione fragmenty kości łonowej i kulszowej bez cech złamania.\nBez wysięku w stawie. Tkanki miękkie bez krwiaka.\n\nWnioski:\n- Bez cech złamania bliższego odcinka kości udowej i panewki stawu biodrowego.\n- Przy utrzymujących się objawach klinicznych do rozważenia MR w kierunku złamania utajonego." },
  { "id": "mr_hip_occult_fracture", "title": "MR Hips trauma (złamanie utajone)", "group": "Trauma", "section": "Pelvis / Hips", "priority": 12,
    "text": "Badanie: MR miednicy i stawów biodrowych bez kontrastu – w kierunku złamania utajonego\n\nOpis:\nBadanie wykonano w sekwencjach T1-zależnych i STIR w płaszczyźnie czołowej oraz T2-zależnych z saturacją tłuszczu w płaszczyźnie poprzecznej.\n\nGłowy, szyjki i okolice krętarzowe obu kości udowych o prawidłowym sygnale szpiku, bez linii złamań i bez obrzęku szpiku kostnego.\nKości łonowe, kulszowe, biodrowe oraz kość krzyżowa bez obrzęku szpiku i bez linii złamań.\nBez wysięku w stawach biodrowych ponad ilość fizjologiczną.\nMięśnie okolicy bioder i miednicy bez cech uszkodzenia, bez krwiaka.\n\nWnioski:\n- Bez cech złamania, w tym złamania utajonego, bliższych odcinków kości udowych i miednicy." },
  { "id": "mr_hip_normal", "title": "MR Hip normal", "group": "Non-trauma", "section": "Pelvis / Hips", "priority": 10,
    "text": "Badanie: MR stawu biodrowego prawego/lewego bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach T1-, T2-zależnych i PD-zależnych z saturacją tłuszczu, w płaszczyznach czołowej, strzałkowej i poprzecznej.\n\nGłowa kości udowej o prawidłowym kształcie i sygnale szpiku, bez cech martwicy.\nSzyjka kości udowej bez obrzęku szpiku.\nChrząstka stawowa zachowana. Szpara stawowa prawidłowej szerokości.\nObrąbek stawowy bez widocznych cech uszkodzenia (ocena ograniczona w badaniu bez artrografii).\nBez wysięku w stawie.\nŚcięgna mięśni pośladkowych średniego i małego ciągłe, o prawidłowym sygnale. Kaletki okołokrętarzowe bez płynu.\nMięśnie okolicy stawu biodrowego o prawidłowym sygnale.\n\nUwidocznione struktury miednicy bez istotnych odchyleń.\n\nWnioski:\n- Obraz MR stawu biodrowego bez istotnych odchyleń od normy." },
  { "id": "mr_sij_normal", "title": "MR Sacroiliac joints normal", "group": "Non-trauma", "section": "Pelvis / Hips", "priority": 11,
    "text": "Badanie: MR stawów krzyżowo-biodrowych bez kontrastu\n\nOpis:\nBadanie wykonano w sekwencjach T1-zależnych i STIR w płaszczyźnie skośnej czołowej (równoległej do długiej osi kości krzyżowej) oraz T2-zależnych z saturacją tłuszczu w płaszczyźnie skośnej poprzecznej.\n\nStawy krzyżowo-biodrowe symetryczne, szpary stawowe prawidłowej szerokości.\nBez obrzęku szpiku podchrzęstnego.\nBez nadżerek, sklerotyzacji podchrzęstnej, stłuszczenia podchrzęstnego ani zrostów kostnych.\nBez płynu w szparach stawowych.\nUwidocznione fragmenty kręgosłupa lędźwiowego i stawów biodrowych bez istotnych zmian.\n\nWnioski:\n- Bez cech aktywnych ani przewlekłych zmian zapalnych w stawach krzyżowo-biodrowych." },
  { "id": "xr_pelvis", "title": "RTG Pelvis", "group": "Trauma", "section": "Pelvis / Hips", "priority": 13,
    "text": "Badanie: RTG miednicy w projekcji AP\n\nOpis:\nPierścień miednicy zachowany.\nNie uwidoczniono linii złamań w obrębie kości biodrowych, łonowych, kulszowych i kości krzyżowej.\nSpojenie łonowe i stawy krzyżowo-biodrowe symetryczne, nieposzerzone.\nGłowy kości udowych prawidłowo osadzone w panewkach.\nSzyjki i okolice krętarzowe kości udowych bez cech złamania. Linie Shentona zachowane obustronnie.\n\nWnioski:\n- Bez radiologicznych cech złamania miednicy i bliższych odcinków kości udowych." },
  { "id": "xr_hip", "title": "RTG Hip", "group": "Trauma", "section": "Pelvis / Hips", "priority": 14,
    "text": "Badanie: RTG stawu biodrowego prawego/lewego w projekcjach AP i osiowej\n\nOpis:\nGłowa kości udowej prawidłowo osadzona w panewce.\nSzyjka kości udowej bez widocznej linii złamania, linia Shentona zachowana.\nKrętarz większy i mniejszy bez cech złamania.\nSzpara stawowa zachowana.\nUwidocznione fragmenty kości łonowej i kulszowej bez cech złamania.\n\nWnioski:\n- Bez radiologicznych cech złamania bliższego odcinka kości udowej." },
  { "id": "xr_chest_pa", "title": "RTG Chest PA", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 10,
    "text": "Badanie: RTG klatki piersiowej w projekcji PA\n\nOpis:\nPłuca bez zmian ogniskowych i bez zagęszczeń miąższowych.\nRysunek naczyniowy płuc prawidłowy.\nWnęki płucne prawidłowe.\nBez cech odmy opłucnowej. Kąty przeponowo-żebrowe wolne.\n\nSylwetka serca niepowiększona. Śródpiersie nieposzerzone, tchawica w linii pośrodkowej.\nKopuły przepony gładkie, prawidłowo położone.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Obraz RTG klatki piersiowej bez istotnych odchyleń od normy." },
  { "id": "xr_chest_ap_trauma", "title": "RTG Chest AP supine trauma", "group": "Trauma", "section": "Chest / Thorax", "priority": 10,
    "text": "Badanie: RTG klatki piersiowej w projekcji AP w pozycji leżącej\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\nOcena w pozycji leżącej ograniczona, w szczególności w zakresie odmy opłucnowej, płynu w jamach opłucnowych oraz szerokości śródpiersia.\n\nPłuca bez ognisk zagęszczeń i bez cech stłuczenia.\nBez widocznych cech odmy opłucnowej, w tym bez objawu głębokiej bruzdy.\nBez cech płynu w jamach opłucnowych.\n\nŚródpiersie nieposzerzone w zakresie oceny w projekcji AP. Zarys łuku aorty zachowany.\nSylwetka serca w granicach normy w zakresie oceny w projekcji AP.\nKopuły przepony o zachowanych zarysach.\n\nNie uwidoczniono złamań żeber, obojczyków i uwidocznionych fragmentów łopatek.\nBez cech rozedmy podskórnej.\n\nWnioski:\n- Bez radiologicznych cech odmy opłucnowej, krwiaka opłucnowego ani złamań w zakresie badania." },
  { "id": "xr_chest_ap_icu", "title": "RTG Chest AP ICU (rurka, cewniki)", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 11,
    "text": "Badanie: RTG klatki piersiowej w projekcji AP w pozycji leżącej (przyłóżkowe)\n\nOpis:\nRurka intubacyjna z końcem w świetle tchawicy, ok. … cm powyżej ostrogi tchawicy.\nCewnik żyły centralnej wprowadzony przez żyłę … z końcem w rzucie żyły głównej górnej.\nZgłębnik żołądkowy z końcem w rzucie żołądka, poniżej przepony.\n\nBez widocznych cech odmy opłucnowej.\nPłuca bez ognisk zagęszczeń miąższowych. Bez cech zastoju w krążeniu płucnym.\nKąty przeponowo-żebrowe wolne.\nSylwetka serca w granicach normy w zakresie oceny w projekcji AP.\n\nWnioski:\n- Rurka intubacyjna, cewnik żyły centralnej i zgłębnik żołądkowy w prawidłowym położeniu.\n- Bez cech odmy opłucnowej." },
  { "id": "xr_ribs", "title": "RTG Ribs", "group": "Trauma", "section": "Chest / Thorax", "priority": 11,
    "text": "Badanie: RTG żeber prawych/lewych w projekcjach celowanych\n\nOpis:\nNie uwidoczniono linii złamań żeber w zakresie badania.\nOdcinki chrzęstne żeber nie podlegają ocenie w badaniu RTG.\nW uwidocznionym zakresie bez cech odmy opłucnowej i bez płynu w jamie opłucnowej.\nBez cech rozedmy podskórnej.\n\nWnioski:\n- Bez radiologicznych cech złamania żeber w zakresie badania." },
  { "id": "xr_sternum", "title": "RTG Sternum", "group": "Trauma", "section": "Chest / Thorax", "priority": 12,
    "text": "Badanie: RTG mostka w projekcji bocznej\n\nOpis:\nRękojeść, trzon mostka i wyrostek mieczykowaty z zachowaną ciągłością warstwy korowej, bez linii złamań.\nPołączenie rękojeści z trzonem mostka prawidłowo ustawione.\nBez poszerzenia tkanek miękkich zamostkowych.\n\nWnioski:\n- Bez radiologicznych cech złamania mostka." },
  { "id": "xr_abdomen_supine", "title": "RTG Abdomen supine", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 10,
    "text": "Badanie: RTG przeglądowe jamy brzusznej w pozycji leżącej\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPrawidłowy rozkład gazów w jelitach. Pętle jelita cienkiego i grubego nieposzerzone.\nGaz obecny w okrężnicy i w odbytnicy.\nBez pośrednich cech wolnego powietrza w jamie otrzewnej (ocena ograniczona w pozycji leżącej).\nNie uwidoczniono cieni złogów w rzucie układu moczowego.\nBez cieniujących ciał obcych.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech niedrożności jelit." },
  { "id": "xr_abdomen_supine_erect", "title": "RTG Abdomen supine + erect", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 11,
    "text": "Badanie: RTG przeglądowe jamy brzusznej w pozycji leżącej i stojącej\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPod kopułami przepony nie uwidoczniono wolnego powietrza.\nPrawidłowy rozkład gazów w jelitach. Pętle jelita cienkiego i grubego nieposzerzone.\nBez patologicznych poziomów płynów w pętlach jelitowych.\nGaz obecny w okrężnicy i w odbytnicy.\nNie uwidoczniono cieni złogów w rzucie układu moczowego.\nBez cieniujących ciał obcych.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech niedrożności jelit.\n- Bez cech wolnego powietrza w jamie otrzewnej." },
  { "id": "xr_chest_erect_free_air", "title": "RTG Chest erect (wolne powietrze)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 12,
    "text": "Badanie: RTG klatki piersiowej w pozycji stojącej – w kierunku wolnego powietrza pod przeponą\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPod kopułami przepony nie uwidoczniono wolnego powietrza.\nPęcherz gazu żołądka w typowym położeniu pod lewą kopułą przepony.\nPłuca w uwidocznionym zakresie bez ognisk zagęszczeń. Bez cech odmy opłucnowej.\nKąty przeponowo-żebrowe wolne.\n\nWnioski:\n- Bez radiologicznych cech wolnego powietrza pod kopułami przepony." },
  { "id": "xr_elbow_child", "title": "RTG Elbow child", "group": "Trauma", "section": "Paediatric", "priority": 10,
    "text": "Badanie: RTG stawu łokciowego prawego/lewego u dziecka w projekcjach AP i bocznej\n\nOpis:\nJądra kostnienia odpowiednie do wieku, prawidłowo położone.\nLinia przednia kości ramiennej przecina środkową trzecią część główki kości ramiennej.\nOś długa kości promieniowej przechodzi przez główkę kości ramiennej.\nNie uwidoczniono linii złamań, w tym złamania nadkłykciowego kości ramiennej.\nNadkłykieć przyśrodkowy prawidłowo położony.\nPrzednia poduszeczka tłuszczowa nieuniesiona, tylna niewidoczna – bez pośrednich cech wysięku w stawie.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu łokciowego." },
  { "id": "xr_forearm_child", "title": "RTG Forearm child", "group": "Trauma", "section": "Paediatric", "priority": 11,
    "text": "Badanie: RTG przedramienia prawego/lewego u dziecka w projekcjach AP i bocznej\n\nOpis:\nKości promieniowa i łokciowa bez cech złamania na całej długości, w tym bez złamań niepełnych i bez wybrzuszenia warstwy korowej.\nChrząstki wzrostowe o prawidłowej szerokości, bez cech uszkodzenia.\nOś długa kości promieniowej przechodzi przez główkę kości ramiennej.\nUwidocznione stawy łokciowy i promieniowo-nadgarstkowy prawidłowo ustawione.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości przedramienia." },
  { "id": "xr_wrist_child", "title": "RTG Wrist child", "group": "Trauma", "section": "Paediatric", "priority": 12,
    "text": "Badanie: RTG nadgarstka prawego/lewego u dziecka w projekcjach PA i bocznej\n\nOpis:\nNasady i przynasady dalsze kości promieniowej i łokciowej bez cech złamania, w tym bez wybrzuszenia warstwy korowej.\nChrząstki wzrostowe o prawidłowej szerokości, bez cech uszkodzenia i bez przemieszczenia nasad.\nJądra kostnienia nadgarstka odpowiednie do wieku.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie nadgarstka." },
  { "id": "xr_chest_child", "title": "RTG Chest child", "group": "Non-trauma", "section": "Paediatric", "priority": 10,
    "text": "Badanie: RTG klatki piersiowej u dziecka\n\nOpis:\nPłuca prawidłowo powietrzne, bez ognisk zagęszczeń miąższowych.\nBez cech pogrubienia ścian oskrzeli. Bez cech rozdęcia płuc.\nBez cech odmy opłucnowej. Kąty przeponowo-żebrowe wolne.\nSylwetka serca i śródpiersie w granicach normy dla wieku.\nBez cieniujących ciał obcych.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Obraz RTG klatki piersiowej bez istotnych odchyleń od normy." },
  { "id": "xr_skeletal_survey_child", "title": "RTG Skeletal survey child", "group": "Trauma", "section": "Paediatric", "priority": 13,
    "text": "Badanie: RTG – przegląd kośćca u dziecka\n\nOpis:\nWykonano projekcje czaszki, klatki piersiowej z projekcjami skośnymi żeber, kręgosłupa, miednicy, kości długich kończyn górnych i dolnych oraz rąk i stóp.\n\nNie uwidoczniono świeżych ani gojących się złamań.\nKości czaszki bez cech złamania.\nŻebra bez cech złamania, w tym w odcinkach tylnych, bez kostniny.\nBez zmian przynasadowych o typie złamań narożnikowych.\nBez odczynów okostnowych.\nGęstość kości, jądra kostnienia i chrząstki wzrostowe odpowiednie do wieku.\n\nWnioski:\n- Bez radiologicznych cech świeżych ani gojących się złamań w przeglądzie kośćca.\n- W przypadku utrzymującego się klinicznego podejrzenia urazu nieprzypadkowego zaleca się kontrolny przegląd kośćca po 11–14 dniach." },
  { "id": "xr_skull_child", "title": "RTG Skull child", "group": "Trauma", "section": "Paediatric", "priority": 14,
    "text": "Badanie: RTG czaszki u dziecka w projekcjach AP i bocznej\n\nOpis:\nNie uwidoczniono linii złamań kości sklepienia czaszki.\nSzwy czaszkowe o prawidłowej szerokości dla wieku.\nBez cech wgłobienia odłamów kostnych.\n\nWnioski:\n- Bez radiologicznych cech złamania kości sklepienia czaszki.\n- Prawidłowy obraz RTG nie wyklucza urazu wewnątrzczaszkowego." },
  { "id": "xr_trauma_chest_pelvis", "title": "RTG Trauma series (chest + pelvis)", "group": "Trauma", "section": "Combined", "priority": 10,
    "text": "Badanie: RTG klatki piersiowej w projekcji AP w pozycji leżącej oraz RTG miednicy w projekcji AP\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nKlatka piersiowa:\nOcena w pozycji leżącej ograniczona.\nBez widocznych cech odmy opłucnowej i bez cech płynu w jamach opłucnowych.\nPłuca bez ognisk zagęszczeń.\nŚródpiersie nieposzerzone w zakresie oceny w projekcji AP.\nNie uwidoczniono złamań żeber i obojczyków.\n\nMiednica:\nPierścień miednicy zachowany.\nNie uwidoczniono linii złamań kości miednicy.\nSpojenie łonowe i stawy krzyżowo-biodrowe nieposzerzone.\nGłowy kości udowych prawidłowo osadzone w panewkach, bliższe odcinki kości udowych bez cech złamania.\n\nWnioski:\n- Bez radiologicznych cech odmy opłucnowej, krwiaka opłucnowego ani złamań w obrębie klatki piersiowej.\n- Bez radiologicznych cech złamania miednicy i zwichnięcia stawów biodrowych." },
  { "id": "snippet_msk_fracture_displaced", "title": "Złamanie z przemieszczeniem", "group": "Snippets", "section": "Trauma snippets", "priority": 10,
    "text": "Złamanie … kości … z przemieszczeniem odłamu dystalnego o ok. … mm ku …, z kątowym ustawieniem odłamów o ok. … stopni, z zajęciem/bez zajęcia powierzchni stawowej." },
  { "id": "snippet_msk_fracture_nondisplaced", "title": "Złamanie bez przemieszczenia", "group": "Snippets", "section": "Trauma snippets", "priority": 11,
    "text": "Złamanie … kości … bez istotnego przemieszczenia odłamów, bez zajęcia powierzchni stawowej." },
  { "id": "snippet_msk_dislocation", "title": "Zwichnięcie", "group": "Snippets", "section": "Trauma snippets", "priority": 12,
    "text": "Zwichnięcie w stawie … z przemieszczeniem … ku …, bez widocznego towarzyszącego złamania." },
  { "id": "snippet_msk_lipohaemarthrosis", "title": "Krwiak stawu z poziomem płyn–tłuszcz", "group": "Snippets", "section": "Trauma snippets", "priority": 13,
    "text": "Wysięk w stawie … z poziomem płyn–tłuszcz (lipohaemarthrosis) – pośredni objaw złamania śródstawowego." },
  { "id": "snippet_msk_vertebral_compression", "title": "Złamanie kompresyjne trzonu", "group": "Snippets", "section": "Trauma snippets", "priority": 14,
    "text": "Złamanie kompresyjne trzonu kręgu … z obniżeniem wysokości przedniej części trzonu o ok. …%, bez zajęcia ściany tylnej trzonu i bez zwężenia kanału kręgowego." },
  { "id": "snippet_msk_burst_fracture", "title": "Złamanie wybuchowe trzonu", "group": "Snippets", "section": "Trauma snippets", "priority": 15,
    "text": "Złamanie wybuchowe trzonu kręgu … z obniżeniem wysokości trzonu o ok. …%, z zajęciem ściany tylnej i retropulsją fragmentu kostnego do kanału kręgowego, powodującą zwężenie jego wymiaru strzałkowego o ok. …%." },
  { "id": "snippet_msk_joint_effusion", "title": "Wysięk w stawie", "group": "Snippets", "section": "MSK snippets", "priority": 10,
    "text": "Wysięk w stawie … w niewielkiej/umiarkowanej/dużej ilości." },
  { "id": "snippet_msk_disc_herniation", "title": "Przepuklina krążka", "group": "Snippets", "section": "MSK snippets", "priority": 11,
    "text": "Na poziomie …/… tylna przepuklina krążka międzykręgowego, przyśrodkowo-boczna po stronie …, modelująca worek oponowy i uciskająca korzeń nerwu … w zachyłku bocznym." },
  { "id": "snippet_msk_canal_stenosis", "title": "Zwężenie kanału kręgowego", "group": "Snippets", "section": "MSK snippets", "priority": 12,
    "text": "Na poziomie …/… zwężenie kanału kręgowego … stopnia, spowodowane uwypukleniem krążka międzykręgowego, przerostem stawów międzywyrostkowych i pogrubieniem więzadeł żółtych; wymiar strzałkowy worka oponowego ok. … mm." },
  { "id": "snippet_msk_osteoporosis", "title": "Osteoporoza", "group": "Snippets", "section": "MSK snippets", "priority": 13,
    "text": "Uogólnione obniżenie gęstości struktury kostnej – obraz mogący odpowiadać osteoporozie." },
  { "id": "snippet_chest_xr_pneumothorax", "title": "Odma opłucnowa (RTG)", "group": "Snippets", "section": "Chest snippets", "priority": 10,
    "text": "Odma opłucnowa po stronie …, z linią opłucnej trzewnej widoczną ok. … mm od ściany klatki piersiowej na wysokości …, bez cech przemieszczenia śródpiersia." },
  { "id": "snippet_chest_xr_pleural_effusion", "title": "Płyn w jamie opłucnowej (RTG)", "group": "Snippets", "section": "Chest snippets", "priority": 11,
    "text": "Płyn w jamie opłucnowej po stronie …, zacieniający kąt przeponowo-żebrowy, sięgający do wysokości … żebra." },
  { "id": "snippet_chest_xr_lines", "title": "Położenie rurki / cewników (RTG)", "group": "Snippets", "section": "Chest snippets", "priority": 12,
    "text": "Rurka intubacyjna z końcem ok. … cm powyżej ostrogi tchawicy. Cewnik żyły centralnej z końcem w rzucie żyły głównej górnej. Zgłębnik żołądkowy z końcem w rzucie żołądka." },
  { "id": "snippet_abdo_xr_sbo", "title": "Niedrożność jelita cienkiego (RTG)", "group": "Snippets", "section": "Abdomen snippets", "priority": 10,
    "text": "Poszerzone pętle jelita cienkiego, o średnicy do ok. … mm, z licznymi poziomami płynów w pozycji stojącej; niewiele gazu w okrężnicy – obraz odpowiadający niedrożności jelita cienkiego." },
];
